var P=30,m=e=>String(e??"").trim().toLowerCase(),v=e=>String(e??"").split(/[\n,;]+/).map(i=>i.trim().toLowerCase().replace(/\.$/,"")).filter(Boolean),f=[{key:"registrar",label:"shared registrar",typeIn:e=>e==="infrastructure.domain",values:e=>e.registrar?[m(e.registrar)]:[]},{key:"nameserver",label:"shared nameserver",typeIn:e=>e==="infrastructure.domain",values:e=>v(e.name_servers)},{key:"asn",label:"same ASN",typeIn:e=>e==="infrastructure.ip_address",values:e=>e.asn?[m(e.asn)]:[]},{key:"certificate",label:"shared certificate",typeIn:e=>e==="infrastructure.certificate",values:e=>e.fingerprint_sha256?[m(e.fingerprint_sha256)]:[]}],w={manifest:{identifier:"run.vineyard.plugins.shared_attribute_clustering",content_type:"vineyard:plugin",name:"Shared-Attribute Clustering",version:"1.1.1",description:'Links nodes that share a registrar or nameserver (Domain), announcing ASN (IP Address) or SHA-256 fingerprint (Certificate), using the selected nodes or, with no selection, the whole graph. Edges are labelled "shared registrar: <value>", "shared nameserver: <value>", "same ASN: <value>" or "shared certificate: <value>"; values shared by more than 30 nodes are skipped and existing edges are not duplicated. Uses only data already on the nodes.',icon:"git-fork",author:{name:"VINEYARD",url:"https://vineyard.run"},license:"Apache-2.0",platforms:{primary:"web",web:{runtime:"sandbox-js",entry:"dist/pack.mjs"}},io:{consumes:[],produces:[]},scopes:{graph:["node:read","edge:read","edge:create"]},lifecycle:{persistence:"opt-in",controls:["progress","cancel"],progress:"determinate"}},async run(e){let i=e.input.selection,d;if(i&&i.length?d=(await Promise.all(i.map(n=>e.graph.get(n)))).filter(Boolean):d=(await e.graph.list()).nodes,d.length<2)return{summary:"Select at least two nodes (or run on a populated graph)",counts:{links:0}};let y=await e.graph.edges(),c=new Set(y.map(n=>`${n.from_node_id}\0${n.to_node_id}\0${n.label}`)),b=(n,r,s)=>c.has(`${n}\0${r}\0${s}`)||c.has(`${r}\0${n}\0${s}`),p=0,l=0,u=0;for(let n=0;n<f.length&&!e.signal?.aborted;n++){let r=f[n];e.progress?.set?.({percent:Math.round((n+1)/f.length*100),message:`Pivoting on ${r.key}`});let s=new Map;for(let a of d)if(r.typeIn(a.type))for(let g of r.values(a.data)){let t=s.get(g)||[];t.push(String(a.id)),s.set(g,t)}for(let[a,g]of s){let t=[...new Set(g)];if(t.length<2)continue;if(t.length>P){u++;continue}l++;let h=`${r.label}: ${a.slice(0,48)}`;for(let o=1;o<t.length&&!e.signal?.aborted;o++)b(t[0],t[o],h)||(await e.graph.createEdge({from:t[0],to:t[o],label:h}),c.add(`${t[0]}\0${t[o]}\0${h}`),p++)}}let k=u?` (${u} over-common cluster(s) skipped)`:"";return{summary:`${p} link(s) across ${l} shared-attribute cluster(s)${k}`,counts:{links:p,clusters:l}}}},S=["Infrastructure attribution from what the graph already holds. Where identity work asks whether two accounts belong to one person, this pack asks whether domains, IP addresses and certificates belong to one operator: it groups nodes by a discriminating attribute they have in common and links the members of each group. It is pure graph analysis, with no network request, no API key and no server.","","## Plugins","","### Shared-Attribute Clustering","","`run.vineyard.plugins.shared_attribute_clustering`","","- **Runs on:** the selected nodes, or every node in the graph when nothing is selected. At least two nodes are needed.","- **Reads:** one property per pivot, each on one node type:","","| Pivot | Node type | Property | Edge label |","|---|---|---|---|","| Registrar | Domain (`infrastructure.domain`) | `registrar` | `shared registrar: <value>` |","| Nameserver | Domain (`infrastructure.domain`) | `name_servers` | `shared nameserver: <value>` |","| ASN | IP Address (`infrastructure.ip_address`) | `asn` | `same ASN: <value>` |","| Certificate | TLS Certificate (`infrastructure.certificate`) | `fingerprint_sha256` | `shared certificate: <value>` |","","- **Adds:** edges only, labelled as above. It creates no nodes and changes no properties.","- **Matching:** values are compared after trimming and lower-casing. `name_servers` is split on newlines, commas and semicolons, with a trailing dot dropped, so each nameserver forms its own group. The value in an edge label is cut to 48 characters.","- **Star links:** a group is linked from its first member to each of the others, so a group of n nodes gets n - 1 edges rather than one per pair. The shared value is in the label, so an edge reads the same in either direction.","- **Over-common values are skipped:** a value shared by more than 30 nodes is not linked, because a value that common does not suggest shared operation. The run summary counts the groups it skipped.","- **Left out on purpose:** country and bare organization, which group far too broadly to imply shared operation.","- **Re-runnable:** an edge with the same label between the same two nodes, in either direction, is not created again.","- The proposed edges are staged for review before they reach the graph. The run reports progress and can be cancelled.","","## Requirements","","- No API key, account or Vineyard-operated service. Runs in the web app; the desktop app is not needed.","- The properties in the table must already be on the nodes. Collection packs write them, so run those first: on a graph without them the plugin finds no groups.","- Graph access: reads nodes and edges, creates edges.","","## What it contacts","","Nothing outside the project. It reads the nodes and edges already in the graph and creates edges between them. No query leaves the app, and no target is contacted.","","## Data and licences","","All input is data already in the project; the pack ships no data set of its own.","","## Source","","https://github.com/Vineyard-Intelligence/pluginpack-shared-attribute-clustering (Apache-2.0)","","`dist/pack.mjs` is built from `src/` with a pinned esbuild, so the published bundle can be checked against the source: `node build.mjs && git diff --exit-code dist/pack.mjs`."].join(`
`),E={identifier:"run.vineyard.pluginpacks.shared_attribute_clustering",content_type:"vineyard:pluginpack",name:"Shared-Attribute Clustering",version:"1.2.0",summary:"Links infrastructure nodes that share a registrar, nameserver, ASN or TLS certificate, using data already in the graph.",description:S,plugins:[w]};export{E as default};
